-- IBGE: API de Malhas v3, RO, intrarregiao=municipio, qualidade=intermediaria.
-- Arquivo de origem SHA-256: 080c2a101d64d8ff8eaa084c3eb2f972ad552c31beb2bcc5e4f50cb41e2f99fe
-- Limites simplificados usados apenas para localizar a regra regional aplicavel.
-- Inclui os municipios cujas caixas envolventes intersectam a caixa do piloto.
CREATE TABLE agro.cereja_municipalities (
  ibge text PRIMARY KEY CHECK (ibge ~ '^[0-9]{7}$'),
  geom extensions.geometry(MultiPolygon, 32720) NOT NULL
);
CREATE INDEX cereja_municipalities_geom_idx ON agro.cereja_municipalities USING gist (geom);

INSERT INTO agro.cereja_municipalities (ibge,geom)
SELECT ibge, extensions.ST_Multi(extensions.ST_CollectionExtract(extensions.ST_MakeValid(
